CREATE TABLE IF NOT EXISTS schema_migrations (version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, verified boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workspaces (id text PRIMARY KEY, owner_id text NOT NULL REFERENCES users(id), settings jsonb NOT NULL, plan text NOT NULL DEFAULT 'trial', billing_status text NOT NULL DEFAULT 'trialing', trial_until bigint NOT NULL, stripe_customer text UNIQUE, stripe_subscription text UNIQUE, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS members (workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('owner','member')), PRIMARY KEY (workspace_id,user_id));
CREATE TABLE IF NOT EXISTS sessions (hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, csrf text NOT NULL, expires_at bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tokens (hash text PRIMARY KEY, user_id text REFERENCES users(id) ON DELETE CASCADE, workspace_id text REFERENCES workspaces(id) ON DELETE CASCADE, purpose text NOT NULL, email text, expires_at bigint NOT NULL, data jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS connections (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, platform text NOT NULL CHECK (platform IN ('instagram','whatsapp')), account_id text NOT NULL, label text NOT NULL, token_cipher text NOT NULL, expires_at bigint, status text NOT NULL DEFAULT 'connected', error text, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (platform,account_id), UNIQUE (workspace_id,platform));
CREATE TABLE IF NOT EXISTS conversations (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, connection_id text REFERENCES connections(id) ON DELETE SET NULL, platform text NOT NULL, external_id text NOT NULL, name text NOT NULL, intent text NOT NULL DEFAULT 'question', status text NOT NULL DEFAULT 'new', auto_send boolean NOT NULL DEFAULT false, unread boolean NOT NULL DEFAULT true, notes text NOT NULL DEFAULT '', memory text NOT NULL DEFAULT '', ai_error text, last_at bigint NOT NULL, window_until bigint NOT NULL, hold_until bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (workspace_id,platform,external_id));
CREATE TABLE IF NOT EXISTS messages (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, conversation_id text NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sender text NOT NULL, text text NOT NULL, timestamp bigint NOT NULL, provider_id text, connection_id text, status text NOT NULL DEFAULT 'received', error text, client_key text, source_id text, automatic boolean NOT NULL DEFAULT false, UNIQUE (connection_id,provider_id), UNIQUE (workspace_id,client_key));
CREATE INDEX IF NOT EXISTS messages_conversation ON messages(workspace_id,conversation_id,timestamp);
CREATE UNIQUE INDEX IF NOT EXISTS messages_one_reply_per_source ON messages(source_id) WHERE source_id IS NOT NULL AND status NOT IN ('failed','cancelled');
CREATE TABLE IF NOT EXISTS drafts (workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, conversation_id text NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, text text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (conversation_id,user_id));
CREATE TABLE IF NOT EXISTS suggestions (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, conversation_id text NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, source_id text NOT NULL REFERENCES messages(id) ON DELETE CASCADE, text text NOT NULL, confidence integer NOT NULL, safe boolean NOT NULL, reason text NOT NULL, model text NOT NULL, latency_ms integer NOT NULL, context_hash text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'ready', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (source_id));
CREATE TABLE IF NOT EXISTS webhook_receipts (id text PRIMARY KEY, platform text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jobs (id text PRIMARY KEY, workspace_id text REFERENCES workspaces(id) ON DELETE CASCADE, kind text NOT NULL, payload jsonb NOT NULL, state text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, available_at bigint NOT NULL, lease_until bigint NOT NULL DEFAULT 0, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS jobs_available ON jobs(state,available_at);
CREATE TABLE IF NOT EXISTS usage (workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, month text NOT NULL, ai_replies integer NOT NULL DEFAULT 0, PRIMARY KEY (workspace_id,month));
CREATE TABLE IF NOT EXISTS audit_events (id text PRIMARY KEY, workspace_id text REFERENCES workspaces(id) ON DELETE CASCADE, actor_id text, action text NOT NULL, resource_id text, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS deletion_requests (code text PRIMARY KEY, request_hash text UNIQUE NOT NULL, completed_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE suggestions ADD COLUMN IF NOT EXISTS context_hash text NOT NULL DEFAULT '';
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;